class PathfindCell
{
public:
	enum { CELL_CLIFF = 2, CELL_OBSTACLE = 4 };

	UnsignedInt costSoFar(PathfindCell *parent);
	void setParentCell(PathfindCell *parent);
	void rva003F6C30(PathfindCellInfo **head);

	__forceinline void allocateInfo(const ICoord2D &pos)
	{
		if (m_info == 0)
		{
			if (g_bfmePathfindFreeList == 0)
				PathfindCellInfo::allocateCellInfos();
			m_info = bfmeAcquirePathfindCellInfo(&g_bfmePathfindFreeList, this, &pos);
		}
		else
		{
			m_info->m_prevOpen = 0;
		}
	}
	Bool hasInfo() const { return m_info != 0; }
	Bool getOpen() const { return ((m_info->m_flags >> 3) & 1) != 0; }
	Bool getClosed() const { return ((m_info->m_flags >> 4) & 1) != 0; }
	void setBlockedByAlly(Bool blocked)
	{
		if (blocked)
			m_info->m_flags |= 1;
		else
			m_info->m_flags &= ~1u;
	}
	UnsignedShort getXIndex() const { return (UnsignedShort)m_info->m_pos.x; }
	UnsignedShort getYIndex() const { return (UnsignedShort)m_info->m_pos.y; }
	UnsignedShort getCostSoFar() const { return m_info->m_costSoFar; }
	void setCostSoFar(UnsignedInt cost) { m_info->m_costSoFar = (UnsignedShort)cost; }
	void setTotalCost(UnsignedInt cost) { m_info->m_totalCost = (UnsignedShort)cost; }
	Int getObstacleID() const { return m_info ? m_info->m_goalAircraftID : 0; }
	Int getType() const { return m_bits & 7; }
	PathfindLayerEnum getLayer() const { return (PathfindLayerEnum)((m_bits >> 6) & 0x3f); }
	Int getConnectLayer() const { return (m_bits >> 12) & 0x3f; }
	Bool getPinched() const { return ((m_bits >> 18) & 1) != 0; }
	Bool bfmeBit24() const { return ((m_bits >> 24) & 1) != 0; }

	PathfindCellInfo *m_info;
	Int m_zone;
	Int m_unused08;
