class Pathfinder
{
public:
	Int iterateCellsAlongLine(const ICoord2D &start, const ICoord2D &end,
		PathfindLayerEnum layer, ExamineCellsStruct *info);
	Bool bfmeStepD4F90(void *info, PathfindCell *cell);
	Bool rva003E0930(const Object *obj, TCheckMovementInfo *info, const ICoord2D *startCell);
	Bool rva003E05B0(const Object *obj, TCheckMovementInfo *info);
	UnsignedInt rva003DB900(PathfindCell *cell, PathfindCell *goalCell);
	void rva003D6400(PathfindCell *cell);

	PathfindCell *getCell(PathfindLayerEnum layer, Int x, Int y)
	{
		if (x >= m_extent.lo.x && x <= m_extent.hi.x &&
			y >= m_extent.lo.y && y <= m_extent.hi.y)
		{
			if (layer > 1 && layer <= 15)
			{
				PathfindCell *cell = m_layers[layer].getCell(x, y);
				if (cell)
					return cell;
			}
			return &m_map[x][y];
		}
		return 0;
	}

protected:
	Int examineNeighboringCells(PathfindCell *parentCell, PathfindCell *goalCell,
		const LocomotorSet &locomotorSet, Bool isHuman, Bool centerInCell,
		Int radius, const ICoord2D &startCellNdx, const Object *obj,
		Int attackDistance);

private:
	unsigned char m_pad00[0x10];
	PathfindCell **m_map;					// +0x010
	IRegion2D m_extent;						// +0x014
	IRegion2D m_logicalExtent;				// +0x024
	unsigned char m_pad34[0x838 - 0x34];
	PathfindCellInfo *m_closedList;			// +0x838
	Bool m_isTunneling;						// +0x83c
	unsigned char m_pad83D[0x844 - 0x83d];
	Int m_ignoreObstacleID;					// +0x844
	unsigned char m_pad848[0x85c - 0x848];
	PathfindLayer m_layers[16];				// +0x85c
	BfmeGridAL m_zoneManager;				// +0xc9c
	unsigned char m_padC9D[0x2470c - 0xc9d];
	ICoord2D *m_bfmeCellsBegin;				// +0x2470c
	ICoord2D *m_bfmeCellsEnd;				// +0x24710
