Int Pathfinder::examineNeighboringCells(PathfindCell *parentCell, PathfindCell *goalCell,
	const LocomotorSet &locomotorSet, Bool isHuman, Bool centerInCell,
	Int radius, const ICoord2D &startCellNdx, const Object *obj,
	Int attackDistance)
{
	Bool canPathThroughUnits = false;
	if (obj->getAIUpdateInterface())
		canPathThroughUnits = obj->getAIUpdateInterface()->canPathThroughUnits();

	if (!m_isTunneling && !locomotorSet.isDownhillOnly() && goalCell)
	{
		ICoord2D start, end;
		start.x = parentCell->getXIndex();
		start.y = parentCell->getYIndex();
		if (m_bfmeCellsBegin == m_bfmeCellsEnd)
		{
			end.x = goalCell->getXIndex();
			end.y = goalCell->getYIndex();
		}
		else
		{
			end = m_bfmeCellsEnd[-1];
		}
		if ((start.x & 3) == 0 && (start.y & 3) == 0)
		{
			ExamineCellsStruct info(this, &locomotorSet, centerInCell, radius, obj,
				isHuman, goalCell, m_bfmeCellsBegin == m_bfmeCellsEnd ? attackDistance : 0);
			iterateCellsAlongLine(start, end, parentCell->getLayer(), &info);
		}
	}

	Int cellCount = 0;
	static Int deltaX[] = { 1, 0, -1, 0, 1, -1, -1, 1 };
	static Int deltaY[] = { 0, 1, 0, -1, 1, 1, -1, -1 };
	const Int numNeighbors = 8;
	const Int firstDiagonal = 4;
	ICoord2D newCellCoord;
	PathfindCell *newCell;
	const Int adjacent[5] = { 0, 1, 2, 3, 0 };
	Bool neighborFlags[8];

	{
		TCheckMovementInfo info;
		info.layer = parentCell->getLayer();
		info.radius = radius;
		info.centerInCell = centerInCell;
		info.m_field14 = 0xc;
		info.m_ignoreObstacleID = obj->getAIUpdateInterface()
			? obj->getAIUpdateInterface()->getIgnoredObstacleID() : 0;
		info.considerTransient = true;
		Int templateLayer = obj->getTemplate()->m_bfme444;
		Bool templateFlag = obj->getTemplate()->m_bfme4CC;
		info.m_step.m_surfaces = locomotorSet.getValidSurfaces();
		{
			BfmeStepFlags flags;
			flags.m_allowAircraftGoal = obj->bfmeIsComputerControlled();
			flags.m_field04 = !templateFlag;
			info.m_step.m_flags = flags;
		}
		info.m_step.m_maxLayer = templateLayer - 1;

		for (Int i = 0; i < numNeighbors; i++)
		{
			neighborFlags[i] = false;
			newCellCoord.x = parentCell->getXIndex() + deltaX[i];
			newCellCoord.y = parentCell->getYIndex() + deltaY[i];

			newCell = getCell(parentCell->getLayer(), newCellCoord.x, newCellCoord.y);
			if (newCell == 0)
				continue;

			if (newCell->hasInfo())
			{
				if (newCell->getClosed() || newCell->getOpen())
					continue;
			}

			if (newCell->getLayer() != parentCell->getLayer() &&
				!(info.m_step.m_surfaces & 0x40) &&
				newCell->getLayer() != parentCell->getConnectLayer() &&
				newCell->getConnectLayer() != parentCell->getLayer())
			{
				if (parentCell->getConnectLayer() != 16 ||
					newCell->getConnectLayer() != parentCell->getConnectLayer())
					continue;
			}

			if (isHuman)
			{
				if (newCellCoord.x < m_logicalExtent.lo.x) continue;
				if (newCellCoord.y < m_logicalExtent.lo.y) continue;
				if (newCellCoord.x > m_logicalExtent.hi.x) continue;
				if (newCellCoord.y > m_logicalExtent.hi.y) continue;
			}

			if (i >= firstDiagonal)
			{
				if (!neighborFlags[adjacent[i - 4]] && !neighborFlags[adjacent[i - 3]])
					continue;
			}

			if (locomotorSet.isDownhillOnly())
			{
				Coord3D fromPos;
				fromPos.x = (Real)(parentCell->getXIndex() * PATHFIND_CELL_SIZE);
				fromPos.y = (Real)(parentCell->getYIndex() * PATHFIND_CELL_SIZE);
				fromPos.z = TheTerrainLogic->getGroundHeight(fromPos.x, fromPos.y);

				Coord3D toPos;
				toPos.x = (Real)(newCellCoord.x * PATHFIND_CELL_SIZE);
				toPos.y = (Real)(newCellCoord.y * PATHFIND_CELL_SIZE);
				toPos.z = TheTerrainLogic->getGroundHeight(toPos.x, toPos.y);

				if (fromPos.z < toPos.z)
					continue;
			}

			Bool movementValid = bfmeStepD4F90(&info.m_step, newCell);
			Bool sameLayerTunnel = false;
			if (m_isTunneling)
				sameLayerTunnel = newCell->getLayer() == parentCell->getLayer();
			Bool dozerHack = false;
			if (!movementValid)
			{
				if (obj->isKindOf((KindOfType)0xe) &&
					newCell->getType() == PathfindCell::CELL_OBSTACLE)
				{
					Object *obstacle = TheGameLogic->findObjectByID(newCell->getObstacleID());
					if (obstacle && obj->getRelationship(obstacle) != ENEMIES)
						dozerHack = true;
				}
				if (!dozerHack && !sameLayerTunnel)
				{
					newCell->allocateInfo(newCellCoord);
					newCell->rva003F6C30(&m_closedList);
					continue;
				}
			}
			if (!dozerHack)
				neighborFlags[i] = true;

			info.cell = newCellCoord;
			if (!rva003E0930(obj, &info, &startCellNdx))
			{
				if (!sameLayerTunnel && !obj->isKindOf((KindOfType)0x6c))
				{
					newCell->allocateInfo(newCellCoord);
					newCell->rva003F6C30(&m_closedList);
					continue;
				}
				info.m_field30++;
			}
			else if (movementValid)
			{
				m_isTunneling = false;
			}

			if (info.m_field30 > 0 && obj->isKindOf((KindOfType)0x6c))
			{
				Bool savedCenter = info.centerInCell;
				Int savedRadius = info.radius;
				info.radius = 1;
				info.centerInCell = true;
				Bool ok = rva003E05B0(obj, &info);
				info.radius = savedRadius;
				info.centerInCell = savedCenter;
				if (!ok)
					continue;
				info.m_field30++;
			}

			if (!newCell->hasInfo())
				cellCount++;
			newCell->allocateInfo(newCellCoord);

			UnsignedInt penalty = 0;
			Int dx, dy;
			if (goalCell)
			{
				dx = abs(newCellCoord.x - goalCell->getXIndex());
				dy = abs(newCellCoord.y - goalCell->getYIndex());
			}
			else
			{
				dx = 3;
				dy = 3;
			}

			if (newCell->getType() == PathfindCell::CELL_CLIFF && !newCell->getPinched())
			{
				Coord3D fromPos;
				fromPos.x = (Real)(parentCell->getXIndex() * PATHFIND_CELL_SIZE);
				fromPos.y = (Real)(parentCell->getYIndex() * PATHFIND_CELL_SIZE);
				fromPos.z = TheTerrainLogic->getGroundHeight(fromPos.x, fromPos.y);

				Coord3D toPos;
				toPos.x = (Real)(newCellCoord.x * PATHFIND_CELL_SIZE);
				toPos.y = (Real)(newCellCoord.y * PATHFIND_CELL_SIZE);
				toPos.z = TheTerrainLogic->getGroundHeight(toPos.x, toPos.y);

				if (fabs(fromPos.z - toPos.z) < PATHFIND_CELL_SIZE_F)
					penalty = 7 * COST_DIAGONAL;
			}
			else if (newCell->getPinched())
			{
				if (dx + dy > 3)
					penalty = COST_ORTHOGONAL;
			}

			newCell->setBlockedByAlly(false);
			if (info.allyFixedCount)
			{
				penalty += COST_DIAGONAL;
				if (!canPathThroughUnits)
					newCell->setBlockedByAlly(true);
			}

			Int costRemaining = 0;
			if (goalCell)
			{
				costRemaining = rva003DB900(newCell, goalCell);
				if (attackDistance && info.allyGoal)
					penalty += 3 * COST_ORTHOGONAL;
			}

			PathfindLayerEnum newLayer = newCell->getLayer();
			if ((newLayer == LAYER_GROUND || newLayer >= 16) &&
				!m_zoneManager.bfmeNearAL(newCellCoord.x, newCellCoord.y) &&
				!newCell->bfmeBit24())
				penalty += 100 * COST_ORTHOGONAL;

			if (newCell->getType() == PathfindCell::CELL_OBSTACLE &&
				newCell->getObstacleID() != m_ignoreObstacleID)
				penalty += 100 * COST_ORTHOGONAL;

			penalty += info.m_field30 * COST_ORTHOGONAL;
			if (m_isTunneling)
			{
				if (!bfmeStepD4F90(&info.m_step, newCell))
					penalty += 10 * COST_ORTHOGONAL;
			}
			if (newCell->bfmeBit24())
				penalty /= 2;

			UnsignedInt newCostSoFar = penalty + newCell->costSoFar(parentCell);
			newCell->setCostSoFar(newCostSoFar);
			newCell->setParentCell(parentCell);
			if (m_isTunneling)
				costRemaining = 0;
			newCell->setTotalCost(newCell->getCostSoFar() + costRemaining);
			rva003D6400(newCell);
		}
	}
	return cellCount;
}
